const chatId = $('When Called by Another Workflow').first().json.chatId;

// Workflows
let workflows = [];
try {
  const wfData = $('Fetch n8n Workflows').first().json;
  workflows = wfData?.data ?? wfData?.workflows ?? [];
} catch(e) {}

const totalWorkflows = workflows.length;
const activeWorkflows = workflows.filter(w => w.active).length;

// Executions
let executions = [];
try {
  const exData = $('Fetch n8n Executions').first().json;
  executions = exData?.data ?? exData?.executions ?? [];
} catch(e) {}

const now = Date.now();
const recent24h = executions.filter(e => {
  const started = new Date(e.startedAt ?? e.created_at ?? 0).getTime();
  return (now - started) < 86400000;
}).length;

const failedCount = executions.filter(e => e.status === 'error' || e.status === 'failed').length;
const successCount = executions.filter(e => e.status === 'success').length;

// Alerts
let firingAlerts = 0;
let alertNames = [];
try {
  const alertData = $('Fetch Prometheus Alerts').first().json;
  const alerts = alertData?.data?.alerts ?? [];
  const firing = alerts.filter(a => a.state === 'firing');
  firingAlerts = firing.length;
  alertNames = firing.map(a => a.labels?.alertname ?? 'Unknown').slice(0, 3);
} catch(e) {}

// Status Icon
const statusIcon = firingAlerts > 0 ? '🔴' : failedCount > 3 ? '🟡' : '🟢';
const statusText = firingAlerts > 0 ? 'Alarm' : failedCount > 3 ? 'Warnung' : 'OK';

const now_str = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit' });

let report = `${statusIcon} *AIOS System Status* — ${statusText}\n\n`;
report += `*n8n Workflows:*\n`;
report += `• Gesamt: ${totalWorkflows} | Aktiv: ${activeWorkflows} | Pausiert: ${totalWorkflows - activeWorkflows}\n\n`;
report += `*Ausführungen (letzte 50):*\n`;
report += `• 24h: ${recent24h} | Erfolg: ${successCount} | Fehler: ${failedCount}\n\n`;
report += `*Prometheus Alerts:*\n`;
if (firingAlerts === 0) {
  report += `• ✅ Keine feuernden Alerts\n`;
} else {
  report += `• 🔴 ${firingAlerts} feuernde Alerts:\n`;
  alertNames.forEach(name => { report += `  - ${name}\n`; });
}
report += `\n_Stand: ${now_str} Uhr_`;

return [{ json: { chatId, response: report } }];
